async function selectFolder(id){if(matchMedia('(max-width:850px)').matches)setTreeVisible(false);stopIndexedSlideshow();indexedSelectedIds.clear();currentFolder=id;const indexed=$('indexedPanel');indexed.replaceChildren();indexed.style.display='none';$('gallery').style.display='';indexedMedia=[];selectedIds.clear();$('search').value='';searchTerm='';localStorage.setItem('dg_folder',id);$('folderTitle').textContent=folderMap.get(id)?.name||(id==='root'?'내 드라이브':'샘플 앨범');renderTree();renderGalleryNav();renderBreadcrumbs();renderAlbums();renderGalleryHome();await load(true);if(currentFolder===id&&['gallery','document'].includes(folderTypes.get(id)))await showIndexedView(id)}
function renderBreadcrumbs(){const el=$('breadcrumbs');el.replaceChildren();const chain=[];let id=currentFolder;const seen=new Set();while(id&&!seen.has(id)&&id!=='root'){seen.add(id);const folder=folderMap.get(id);if(!folder){chain.unshift({id,name:'폴더'});break}chain.unshift({id,name:folder.name});const parent=folder.parents?.[0];if(!parent||parent==='root'||!folderMap.has(parent))break;id=parent}chain.unshift({id:'root',name:demoTree?'샘플 드라이브':'내 드라이브'});chain.forEach((entry,i)=>{if(i){const sep=document.createElement('span');sep.textContent='›';el.append(sep)}const btn=document.createElement('button');btn.textContent=entry.name;btn.onclick=async()=>{if(entry.id===currentFolder)return;treeExpanded.add(entry.id);await selectFolder(entry.id)};el.append(btn)})}
async function scanDuplicates(){const host=$('organizePreview');$('organizeDialog').style.display='flex';$('organizeApply').disabled=true;host.textContent='중복 검사 중…';$('organizeStatus').textContent='Drive MD5 체크섬 기반으로 검사합니다. 파일은 삭제하지 않습니다.';try{const d=await get('/apps/file/drive_manager/api/duplicates?folder='+encodeURIComponent(currentFolder));host.replaceChildren();for(const [i,group] of d.groups.entries()){const h=document.createElement('h4');h.textContent='중복 그룹 '+(i+1)+' · '+group.length+'개';host.append(h);for(const f of group){const line=document.createElement('div');line.textContent=f.name+' ('+Math.round(Number(f.size||0)/1024)+' KB)';host.append(line)}}$('organizeStatus').textContent=d.scanned+'개 검사 · 중복 그룹 '+d.groups.length+'개'+(d.truncated?' · 5000개 제한':'');if(!d.groups.length)host.textContent='중복 파일이 발견되지 않았습니다.'}catch(e){host.textContent='검사 실패: '+e.message}}
let organizePlan=[],organizeParent='',organizeScanVersion=0,organizeShowAll=false,organizeReady=false;function updateOrganizeApply(){$('organizeApply').disabled=!organizeReady||!$('organizeConfirm').checked}function renderOrganizeSample(){const host=$('organizePreview');host.replaceChildren();const count=Number($('organizeSampleCount').value),layout=$('organizeLayout').value,shown=organizeShowAll?organizePlan:organizePlan.slice(0,count);$('organizeShowAll').textContent=organizeShowAll?'샘플만 보기':'전체 대상 조회 및 예상 결과 보기';const intro=document.createElement('p');intro.textContent=`예상 이동 결과 ${shown.length}개 표시 / ${organizeShowAll?'조회된 전체':'샘플'} ${organizePlan.length}개 · 실제 파일은 이동하지 않았습니다.`;host.append(intro);for(const f of shown){const row=document.createElement('div');row.style.cssText='padding:9px 4px;border-bottom:1px solid var(--border);overflow-wrap:anywhere';const from=document.createElement('div');from.textContent='현재: '+f.path+'/'+f.name;from.style.opacity='.75';const to=document.createElement('div');const dest=layout==='year'?f.year:layout==='flat-month'?f.year+'-'+f.month:f.year+'/'+f.month;to.textContent='예상: '+f.path+'/'+dest+'/'+f.name+' ('+(f.source==='capture'?'촬영일':'Drive 생성일')+')';row.append(from,to);host.append(row)}}async function previewExisting(full=false){const version=++organizeScanVersion;organizeParent=currentFolder;organizePlan=[];organizeShowAll=full;organizeReady=false;$('organizeConfirm').checked=false;const recursive=$('organizeRecursive').checked,layout=$('organizeLayout').value,types=$('organizeTypes').value,dateMode=$('organizeDate').value,skipStructured=$('organizeSkipStructured').checked;$('organizeDialog').style.display='flex';const host=$('organizePreview');host.textContent='Drive 파일 확인 중…';$('organizeApply').disabled=true;const sampleLimit=full?Infinity:Number($('organizeSampleCount').value);const queue=[{id:organizeParent,path:folderMap.get(organizeParent)?.name||'내 드라이브'}],visited=new Set();let truncated=false;try{while(queue.length&&organizePlan.length<sampleLimit){if(version!==organizeScanVersion)return;if(visited.size>=300){truncated=true;break}const folder=queue.shift();if(visited.has(folder.id))continue;visited.add(folder.id);$('organizeStatus').textContent=`${visited.size}개 폴더 확인 중 · 대기 ${queue.length}개`;if(skipStructured&&folder.id!==organizeParent&&/(?:^|\/)(?:20\d{2})(?:\/|$|[-_](?:0[1-9]|1[0-2])$)/.test(folder.path))continue;const d=await get('/apps/file/drive_manager/api/organize/preview?folder='+encodeURIComponent(folder.id)+'&types='+types+'&date='+dateMode+'&limit='+ (full?0:Math.max(1,sampleLimit-organizePlan.length)));for(const f of d.files||[])organizePlan.push({...f,parent:folder.id,path:folder.path});if(d.truncated&&full)truncated=true;if(organizePlan.length>=sampleLimit)break;if(recursive){let token='',pages=0;do{const children=await get('/apps/file/drive_manager/api/folder-children?parent='+encodeURIComponent(folder.id)+(token?'&pageToken='+encodeURIComponent(token):''));for(const child of children.folders||[])if(!visited.has(child.id))queue.push({id:child.id,path:folder.path+'/'+child.name});token=children.nextPageToken||'';pages++}while(token&&pages<100);if(token)truncated=true}}renderOrganizeSample();$('organizeStatus').textContent=`${visited.size}개 폴더 · ${organizePlan.length}개 대상`+(truncated?' · 일부 항목 미조회 (300개 폴더 또는 페이지 제한)':'')+(full?' · 전체 조회':' · 샘플 조회 완료');organizeReady=full&&!!organizePlan.length&&!truncated;updateOrganizeApply();if(truncated)host.prepend(document.createTextNode('안전상 일부 항목이 누락될 수 있어 실행을 제한했습니다.\n'))}catch(e){host.textContent='조회 실패: '+e.message;$('organizeApply').disabled=true}}
async function applyExisting(){if(!organizeReady||!$('organizeConfirm').checked||!organizePlan.length)return;if(!await ask(`${organizePlan.length}개 파일을 각 원본 폴더 안의 연도/월 폴더로 실제 이동합니다. 계속할까요?`))return;const layout=$('organizeLayout').value;const btn=$('organizeApply');btn.disabled=true;let ok=0,failed=0;const groups=new Map();for(const f of organizePlan){if(!groups.has(f.parent))groups.set(f.parent,[]);groups.get(f.parent).push(f)}try{for(const [parent,files] of groups){for(let i=0;i<files.length;i+=100){$('organizeStatus').textContent=`정리 중 · 성공 ${ok}개 / 실패 ${failed}개`;const r=await fetch('/apps/file/drive_manager/api/organize/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({parent,layout,files:files.slice(i,i+100).map(f=>({id:f.id}))})});const d=await r.json();if(!r.ok)throw Error(d.error||'정리 실패');for(const x of d.results||[]){if(x.ok)ok++;else failed++}}childCache.delete(parent)}$('organizeStatus').textContent=`이동 완료 ${ok}개, 실패 ${failed}개`;await fetchChildren(organizeParent);renderTree();renderAlbums();await load(true)}catch(e){$('organizeStatus').textContent='오류: '+e.message}finally{btn.disabled=false}}
async function manageSharesUI(){try{const d=await get('/apps/file/drive_manager/api/shares');if(!d.shares?.length)return notice('활성 공유가 없습니다.');const lines=d.shares.map((x,i)=>`${i+1}. ${x.name} (${x.mode}) · ${new Date(x.expires*1000).toLocaleDateString()} 만료 · 방문 ${x.visits||0} · 열람 ${x.views||0} · 다운로드 ${x.downloads||0}`).join('\n');const num=Number(await askValue('공유 목록\n'+lines+'\n\n해제할 번호를 입력하세요. 취소는 빈칸.', ''));if(!Number.isInteger(num)||num<1||num>d.shares.length)return;const x=d.shares[num-1];const action=await askValue('1: 접근 기록 / 2: 공유 해제 / 3: 만료일 / 4: 다운로드 / 5: 암호 / 6: 게스트 업로드','1');if(action==='1'){const audit=await get('/apps/file/drive_manager/api/share-audit?id='+encodeURIComponent(x.id));notice((audit.events||[]).slice(0,50).map(e=>new Date(e.timestamp*1000).toLocaleString()+' '+e.kind+' '+(e.fileId||'')).join('\n')||'기록이 없습니다.');return}if(action==='3'||action==='4'||action==='5'||action==='6'){let payload={id:x.id};if(action==='3'){const days=Number(await askValue('지금부터 유효기간 (1~365일)','7'));if(!Number.isInteger(days)||days<1||days>365)return;payload.days=days}else if(action==='4'){const choice=await choose('다운로드 허용',['허용','차단']);if(choice===null)return;payload.download=choice===0}else if(action==='5'){const password=await askValue('새 암호 (8자 이상), 비우면 암호 해제','');if(password===null||password&&password.length<8)return;payload.password=password}else{const choice=await choose('게스트 업로드 허용',['허용','차단']);if(choice===null)return;payload.upload=choice===0}const update=await fetch('/apps/file/drive_manager/api/shares/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!update.ok)throw Error('공유 설정 변경 실패');notice('공유 설정 변경 완료');return}if(action!=='2'||!await ask(x.name+' 공유를 즉시 해제할까요?'))return;await confirmedWrite('share.revoke','/apps/file/drive_manager/api/shares/revoke',{id:x.id});notice('공유 해제 완료')}catch(e){notice(e.message)}}
async function shareFolderUI(selectedFiles=null){const shareFolder=currentFolder;if(shareFolder==='root'){notice('공유할 폴더를 선택하세요.');return}const name=await askValue('공유 이름',folderMap.get(shareFolder)?.name||'공유 폴더');if(!name)return;const modeChoice=await choose('공유 표시 방식',['갤러리','파일 목록']);if(modeChoice===null)return;const mode=modeChoice===0?'gallery':'files';const dlChoice=await choose('외부 사용자 다운로드',['허용','차단']);if(dlChoice===null)return;const download=dlChoice===0;const password=await askValue('공유 암호 (선택 사항, 설정하려면 8자 이상)','');if(password===null)return;if(password&&password.length<8)return notice('암호는 8자 이상이어야 합니다');const dayInput=await askValue('공유 유효기간 (일)', '7');if(dayInput===null)return;const days=Number(dayInput);if(!Number.isInteger(days)||days<1||days>365)return notice('1~365일로 입력하세요');if(!await ask('「'+name+'」 공유를 생성할까요?\n대상 폴더: '+(folderMap.get(shareFolder)?.name||shareFolder)+'\n유효기간: '+days+'일 · 다운로드: '+(download?'허용':'차단')+' · 암호: '+(password?'설정':'미설정')))return;try{const d=await confirmedWrite('share.create','/apps/file/drive_manager/api/shares',{folder:shareFolder,name,mode:selectedFiles?'gallery':mode,download,days,password,...(selectedFiles?{files:selectedFiles}:{})});await askValue('공유 링크 (복사하세요)',d.url)}catch(e){notice(e.message)}}
async function createFolderUI(){const name=await askValue('새 폴더 이름');if(!name)return;try{const r=await fetch('/apps/file/drive_manager/api/create-folder',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({parent:currentFolder,name})});const d=await r.json();if(!r.ok)throw Error(d.error||'폴더 생성 실패');childCache.delete(currentFolder);await fetchChildren(currentFolder);treeExpanded.add(currentFolder);renderTree();renderAlbums();$('status').textContent='폴더 생성 완료: '+d.name}catch(e){notice(e.message+'\nGoogle Drive 쓰기 권한이 없다면 다시 로그인해야 합니다.')}}
async function captureMonth(file){try{if(!/\.jpe?g$/i.test(file.name))throw Error('not JPEG');const buffer=await file.slice(0,262144).arrayBuffer(),v=new DataView(buffer);let pos=2;while(pos+4<v.byteLength){if(v.getUint8(pos)!==255)break;const marker=v.getUint8(pos+1),len=v.getUint16(pos+2);if(marker===225&&pos+len+2<=v.byteLength&&String.fromCharCode(...new Uint8Array(buffer,pos+4,4))==='Exif'){const base=pos+10,little=v.getUint16(base)===0x4949;const u16=o=>v.getUint16(base+o,little),u32=o=>v.getUint32(base+o,little);const readIfd=(off,tag)=>{if(base+off+2>v.byteLength)return null;const count=u16(off);for(let i=0;i<Math.min(count,256);i++){const at=off+2+i*12;if(base+at+12>v.byteLength)break;if(u16(at)===tag)return {type:u16(at+2),count:u32(at+4),value:u32(at+8)}}return null};const root=readIfd(u32(4),0x8769);if(root){const dt=readIfd(root.value,0x9003)||readIfd(root.value,0x9004);if(dt&&dt.count>=19&&base+dt.value+19<=v.byteLength){const str=new TextDecoder().decode(new Uint8Array(buffer,base+dt.value,19));const m=/^(20\d{2}):(0[1-9]|1[0-2]):/.exec(str);if(m)return {month:m[1]+'-'+m[2],source:'EXIF 촬영일'}}}}pos+=len+2}}catch(e){}const date=new Date(file.lastModified||Date.now());return {month:date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0'),source:'파일 수정일'}}
async function renderUploadPreview(){const files=Array.from($('uploadFiles').files||[]);$('uploadPreview').replaceChildren();for(const f of files){const div=document.createElement('div');div.textContent=f.name+' · 날짜 확인 중…';$('uploadPreview').append(div);const date=await captureMonth(f);if(!div.isConnected)continue;div.textContent=f.name+' ('+(f.size/1048576).toFixed(1)+' MB) → '+($('autoOrganize').checked?date.month.replace('-','/')+'/':'현재 폴더 /')+' ['+date.source+']'}$('uploadStatus').textContent=files.length+'개 파일 선택 · 저장 위치: '+(folderMap.get(uploadTargetFolder||currentFolder)?.name||'내 드라이브')}
function setupDragDrop(){const zone=document.querySelector('.tree-panel');let depth=0;const hasFiles=e=>Array.from(e.dataTransfer?.types||[]).includes('Files');zone.addEventListener('dragenter',e=>{if(!hasFiles(e))return;e.preventDefault();depth++;$('dropZone').classList.add('drag-over')});zone.addEventListener('dragover',e=>{if(!hasFiles(e))return;e.preventDefault();e.dataTransfer.dropEffect='copy';$('dropZone').classList.add('drag-over')});zone.addEventListener('dragleave',e=>{if(!hasFiles(e))return;depth=Math.max(0,depth-1);if(!depth)$('dropZone').classList.remove('drag-over')});zone.addEventListener('drop',async e=>{if(!hasFiles(e))return;e.preventDefault();depth=0;$('dropZone').classList.remove('drag-over');if(currentFolder==='demo'||currentFolder.startsWith('demo-')){notice('샘플 폴더에는 업로드할 수 없습니다. Google Drive 폴더를 선택하세요.');return}await prepareDroppedFiles(e.dataTransfer.files,currentFolder)})}
async function prepareDroppedFiles(fileList,folderId){if(folderId==='demo'||folderId.startsWith('demo-'))return notice('샘플 폴더에는 업로드할 수 없습니다.');const files=Array.from(fileList||[]).filter(f=>f.size>0);if(!files.length)return;try{const transfer=new DataTransfer();for(const f of files)transfer.items.add(f);$('uploadFiles').files=transfer.files}catch(e){return notice('파일 선택을 처리하지 못했습니다. 업로드 버튼을 사용하세요.')}cancelUploadAutoClose();uploadTargetFolder=folderId;$('uploadDialog').style.display='flex';await renderUploadPreview()}
async function uploadFiles(){const files=Array.from($('uploadFiles').files||[]);if(!files.length)return;const target=uploadTargetFolder||currentFolder;const button=$('uploadStart');cancelUploadAutoClose();button.disabled=true;const auto=$('autoOrganize').checked;let done=0,processed=0;const errors=[];const started=performance.now();let sent=0;const update=()=>{const sec=Math.max(1,(performance.now()-started)/1000);$('uploadStatus').textContent=`${done}/${files.length}개 완료 · ${Math.round(sent/1048576)} MB 전송 · ${(sent/1048576/sec).toFixed(1)} MB/s`};async function uploadOne(f){if(f.size>5*1024**3)throw Error('5GB 초과');const mime=f.type||'application/octet-stream';const date=auto?await captureMonth(f):{month:'2026-01'};const resumeKey='dm-upload:'+target+':'+f.name+':'+f.size+':'+f.lastModified+':'+auto;let info=null,offset=0;try{const saved=JSON.parse(localStorage.getItem(resumeKey)||'null');if(saved?.uploadId){const check=await fetch('/apps/file/drive_manager/api/upload/status?id='+encodeURIComponent(saved.uploadId));if(check.ok){const state=await check.json();info=saved;offset=state.next||0;if(state.complete){localStorage.removeItem(resumeKey);return}}else localStorage.removeItem(resumeKey)}}catch(e){localStorage.removeItem(resumeKey)}if(!info){const init=await fetch('/apps/file/drive_manager/api/upload/resumable',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({parent:target,name:f.name,mime,size:f.size,auto,month:date.month})});info=await init.json();if(!init.ok)throw Error(info.error||'업로드 시작 실패');localStorage.setItem(resumeKey,JSON.stringify(info))}while(offset<f.size){const end=Math.min(offset+info.chunkSize,f.size);let response;for(let attempt=0;attempt<3;attempt++){try{response=await fetch('/apps/file/drive_manager/api/upload/chunk/'+info.uploadId,{method:'PUT',headers:{'Content-Range':`bytes ${offset}-${end-1}/${f.size}`},body:f.slice(offset,end)});if(!response.ok)throw Error('전송 오류 '+response.status);break}catch(e){if(attempt===2)throw e;await new Promise(r=>setTimeout(r,1000*(attempt+1)))}}const result=await response.json();const next=result.complete?f.size:(result.next??end);sent+=Math.max(0,next-offset);offset=next;update()}localStorage.removeItem(resumeKey)}try{const workers=Array.from({length:Math.min(3,files.length)},async()=>{while(processed<files.length){const i=processed++;const f=files[i];try{await uploadOne(f);done++}catch(e){errors.push(f.name+': '+e.message)}update()}});await Promise.all(workers);$('uploadStatus').textContent=`${done}/${files.length}개 업로드 완료`+(errors.length?' · 실패: '+errors.join('; '):'');childCache.delete(target);await fetchChildren(target);renderTree();if(currentFolder===target){renderAlbums();await load(true)}uploadTargetFolder=null;if(errors.length===0&&done===files.length){$('uploadStatus').textContent=`${done}개 업로드 완료 · 3초 후 자동으로 닫힙니다.`;uploadCloseTimer=setTimeout(()=>{uploadCloseTimer=null;$('uploadDialog').style.display='none';$('uploadFiles').value='';$('uploadPreview').replaceChildren()},3000)}}finally{button.disabled=false}}
async function loadFavorites(){try{const r=await get('/apps/file/drive_manager/api/favorites');favorites=new Set(r.ids||[]);renderMedia()}catch(e){console.warn('favorites unavailable')}}
async function toggleFavorite(id){const active=!favorites.has(id);const r=await fetch('/apps/file/drive_manager/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,active})});if(!r.ok)throw Error('즐겨찾기 저장 실패');if(active)favorites.add(id);else favorites.delete(id);renderMedia()}
let indexedMedia=[];let indexedSlideshowTimer=null;function stopIndexedSlideshow(){if(indexedSlideshowTimer){clearInterval(indexedSlideshowTimer);indexedSlideshowTimer=null}}function startIndexedSlideshow(){stopIndexedSlideshow();if(!indexedMedia.length)return;openIndexedPhoto(0);indexedSlideshowTimer=setInterval(()=>{const modal=$('indexedLightbox');if(!modal||modal.style.display!=='flex'){stopIndexedSlideshow();return}const next=(Number(modal.dataset.index)+1)%indexedMedia.length;openIndexedPhoto(next)},4000)}
function openIndexedPhoto(index){const f=indexedMedia[index];if(!f)return;let modal=$('indexedLightbox');if(!modal){modal=document.createElement('div');modal.id='indexedLightbox';modal.className='indexed-lightbox';modal.innerHTML='<button class="indexed-close" aria-label="닫기">✕</button><button class="indexed-prev" aria-label="이전">‹</button><div class="indexed-stage"></div><button class="indexed-next" aria-label="다음">›</button><div class="indexed-caption"></div>';$('dm-overlays').append(modal);modal.querySelector('.indexed-close').onclick=()=>{stopIndexedSlideshow();modal.style.display='none'};modal.querySelector('.indexed-prev').onclick=()=>openIndexedPhoto((Number(modal.dataset.index)-1+indexedMedia.length)%indexedMedia.length);modal.querySelector('.indexed-next').onclick=()=>openIndexedPhoto((Number(modal.dataset.index)+1)%indexedMedia.length);modal.addEventListener('click',e=>{if(e.target===modal){stopIndexedSlideshow();modal.style.display='none'}});document.addEventListener('keydown',e=>{if(modal.style.display!=='flex')return;if(e.key==='Escape'){stopIndexedSlideshow();modal.style.display='none'};if(e.key==='ArrowLeft')modal.querySelector('.indexed-prev').click();if(e.key==='ArrowRight')modal.querySelector('.indexed-next').click()})}modal.dataset.index=index;const stage=modal.querySelector('.indexed-stage');stage.replaceChildren();const el=document.createElement(f.mimeType?.startsWith('video/')?'video':'img');el.src='/apps/file/drive_manager/api/media/'+encodeURIComponent(f.id);if(el.tagName==='VIDEO'){el.controls=true;el.autoplay=true}el.alt=f.name;stage.append(el);modal.querySelector('.indexed-caption').textContent=f.name+' · '+(f.captureTime||f.createdTime||'').slice(0,10)+' · '+(index+1)+' / '+indexedMedia.length;modal.style.display='flex'}
async function albumRequest(payload){const r=await fetch('/apps/file/drive_manager/api/virtual-albums',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error||'앨범 처리 실패');return d}
async function addToVirtualAlbum(file){try{const data=await get('/apps/file/drive_manager/api/virtual-albums');let albums=data.albums||[];const options=albums.map((a,i)=>(i+1)+'. '+a.name).join('\n');const selected=await askValue('추가할 가상 앨범 번호를 입력하세요. 새 앨범은 이름을 입력하세요.\n'+options);if(!selected)return;let album=albums[Number(selected)-1];if(!album){const created=await albumRequest({action:'create',name:selected});album={id:created.id,name:created.name}}await albumRequest({action:'add',album:album.id,id:file.id});notice('가상 앨범에 추가했습니다: '+album.name)}catch(e){notice(e.message)}}
